# -*- coding: utf-8 -*-

import re
import shlex

from .common._base import BaseCheck


CONFIG = {'mode': 'ioscan',
 'device_class': 'fc',
 'allowed_states_key': 'allowed_hba_states',
 'expected_count_key': 'expected_hba_count',
 'case_name': 'hpux_os_hba_connection_ioscan_check',
 'item_name': 'HBA 연결상태 점검',
 'commands': ['ioscan -fnC fc'],
 'thresholds': [{'name': 'expected_hba_count', 'default': 0, 'type': 'int'},
                {'name': 'allowed_hba_states', 'default': 'CLAIMED', 'type': 'str'}]}
BECOME_USER_MARKER = '__BECOME_USER__:'


class Check(BaseCheck):
    USE_HOST_CONNECTION = True
    CONNECTION_METHOD = 'ssh'

    def _thresholds(self):
        values = {}
        for spec in CONFIG.get('thresholds', []):
            name = spec.get('name')
            if not name:
                continue
            values[name] = self.get_threshold_var(
                name,
                default=spec.get('default'),
                value_type=spec.get('type') or 'str',
            )
        return values

    def _is_become_enabled(self):
        become_raw = self.get_application_credential_value('become', default=False)
        return str(become_raw).strip().lower() == 'true'

    def _mask_command_history(self, *secrets):
        if not self._command_history:
            return
        masked_cmd = self._command_history[-1].get('cmd', '')
        for secret in secrets:
            if secret:
                masked_cmd = masked_cmd.replace(secret, '*****')
        self._command_history[-1]['cmd'] = masked_cmd

    def _build_command(self, command):
        if not self._is_become_enabled():
            return command

        become_method = str(self.get_application_credential_value('become_method', default='su -') or 'su -').strip().lower()
        become_user = str(self.get_application_credential_value('become_user', default='root') or 'root').strip() or 'root'
        become_password = str(self.get_application_credential_value('become_password', default='') or '')
        normalized_become_method = ' '.join(become_method.split())

        if normalized_become_method not in ('su', 'su -'):
            raise ValueError(f'unsupported become_method: {become_method}')

        become_script = 'current_user=$(whoami); echo {marker}${{current_user}}; {command}'.format(
            marker=BECOME_USER_MARKER,
            command=command,
        )
        return "printf '%s\\n' {password} | su - {user} -c {command}".format(
            password=shlex.quote(become_password),
            user=shlex.quote(become_user),
            command=shlex.quote(become_script),
        )

    def _strip_become_marker(self, output):
        if not self._is_become_enabled():
            return output or '', ''

        lines = (output or '').splitlines()
        marker_line = next((line.strip() for line in lines if line.strip().startswith(BECOME_USER_MARKER)), '')
        if not marker_line:
            raise ValueError('권한 상승 후 사용자 확인 결과를 찾지 못했습니다.')

        actual_user = marker_line.split(BECOME_USER_MARKER, 1)[1].strip()
        expected_user = str(self.get_application_credential_value('become_user', default='root') or 'root').strip() or 'root'
        if actual_user != expected_user:
            raise ValueError(f'권한 상승 사용자가 기대값과 다릅니다: expected={expected_user}, actual={actual_user}')

        cleaned_lines = [line for line in lines if not line.strip().startswith(BECOME_USER_MARKER)]
        return '\n'.join(cleaned_lines).strip(), actual_user

    def _run_commands(self):
        outputs = []
        mode = CONFIG.get('mode')

        for command in CONFIG.get('commands', []):
            try:
                actual_command = self._build_command(command)
            except ValueError as exc:
                return None, self.fail('권한 상승 설정 오류', message=str(exc))

            become_password = str(self.get_application_credential_value('become_password', default='') or '')
            rc, out, err = self._ssh(actual_command)
            self._mask_command_history(become_password)

            if self._is_connection_error(rc, err):
                return None, self.fail(
                    '호스트 연결 실패',
                    message=(err or 'SSH 연결 확인에 실패했습니다.').strip(),
                    stderr=(err or '').strip(),
                )

            try:
                clean_out, actual_become_user = self._strip_become_marker(out)
            except ValueError as exc:
                return None, self.fail(
                    '권한 상승 사용자 확인 실패',
                    message=str(exc),
                    stdout=(out or '').strip(),
                    stderr=(err or '').strip(),
                )

            log_no_match = mode == 'log' and rc == 1 and not (clean_out or '').strip()
            if rc != 0 and not log_no_match:
                return None, self.fail(
                    '점검 명령 실행 실패',
                    message=f'{command} 명령 실행에 실패했습니다.',
                    stdout=(clean_out or '').strip(),
                    stderr=(err or '').strip(),
                )

            command_error = self._detect_command_error(clean_out, err)
            if command_error and not log_no_match:
                return None, self.fail(
                    '점검 명령 실행 실패',
                    message=f'{command} 명령 출력에서 실행 오류가 확인되었습니다: {command_error}',
                    stdout=(clean_out or '').strip(),
                    stderr=(err or '').strip(),
                )

            outputs.append({
                'command': command,
                'rc': rc,
                'stdout': (clean_out or '').strip(),
                'stderr': (err or '').strip(),
                'become_user': actual_become_user,
            })

        return outputs, None

    def _split_list(self, value):
        return [token.strip() for token in re.split(r'[|,\n]+', str(value or '')) if token.strip()]

    def _parse_float(self, value, default=None):
        try:
            return float(str(value).strip().rstrip('%'))
        except (TypeError, ValueError):
            return default

    def _parse_int(self, value, default=None):
        parsed = self._parse_float(value, default=None)
        if parsed is None:
            return default
        return int(parsed)

    def _combined_stdout(self, outputs):
        return '\n'.join(item.get('stdout', '') for item in outputs if item.get('stdout', '')).strip()

    def run(self):
        outputs, error = self._run_commands()
        if error:
            return error
        return self._evaluate(outputs)

    def _evaluate(self, outputs):
        thresholds = self._thresholds()
        text = outputs[0]['stdout']
        device_class = CONFIG.get('device_class')
        allowed_key = CONFIG.get('allowed_states_key', 'allowed_states')
        expected_key = CONFIG.get('expected_count_key', 'expected_count')
        allowed_states = {token.upper() for token in self._split_list(thresholds.get(allowed_key, 'CLAIMED'))}
        expected_count = self._parse_int(thresholds.get(expected_key, 0), 0)
        devices = []
        abnormal = []

        for line in text.splitlines():
            parts = line.split()
            if len(parts) < 6 or parts[0].lower() != device_class:
                continue
            state = parts[4].upper()
            item = {
                'class': parts[0],
                'instance': parts[1],
                'hw_path': parts[2],
                'driver': parts[3],
                'state': state,
                'hw_type': parts[5],
                'description': ' '.join(parts[6:]),
            }
            devices.append(item)
            if state not in allowed_states:
                abnormal.append(item)

        if not devices:
            return self.fail('장치 정보 없음', message=f'ioscan 결과에서 {device_class} 장치를 찾지 못했습니다.', stdout=text)
        if expected_count and len(devices) < expected_count:
            return self.fail('장치 수 부족', message=f'{device_class} 장치 수가 기대값보다 적습니다: current={len(devices)}, expected={expected_count}', stdout=text)
        if abnormal:
            return self.fail('장치 상태 비정상', message='비정상 ioscan 상태가 확인되었습니다: ' + ', '.join(f"{x['hw_path']}={x['state']}" for x in abnormal), stdout=text)

        return self.ok(
            metrics={'device_count': len(devices), 'devices': devices, 'abnormal_devices': abnormal},
            thresholds={expected_key: expected_count, allowed_key: '|'.join(sorted(allowed_states))},
            reasons=f'{device_class} 장치 {len(devices)}개가 정상 상태입니다.',
            message=f'ioscan 기준 {CONFIG.get("item_name")} 점검이 정상 수행되었습니다.',
        )


CHECK_CLASS = Check

# -*- coding: utf-8 -*-

import re

from .common._base import BaseCheck


IOSCAN_COMMAND = 'ioscan -m dsf'


class Check(BaseCheck):
    USE_HOST_CONNECTION = True
    CONNECTION_METHOD = 'ssh'

    def _parse_int(self, value, default=0):
        try:
            return int(str(value).strip())
        except (TypeError, ValueError):
            return default

    def _parse_ioscan_disks(self, text):
        disks = []
        current = None

        for raw_line in (text or '').splitlines():
            line = raw_line.rstrip()
            stripped = line.strip()
            if not stripped or stripped.startswith('Persistent DSF') or stripped.startswith('='):
                continue

            match = re.match(r'^(/dev/rdisk/\S+)\s+(.+)$', line)
            if match:
                current = {
                    'persistent_dsf': match.group(1),
                    'legacy_dsfs': re.findall(r'/dev/rdsk/\S+', match.group(2)),
                }
                disks.append(current)
                continue

            if current and line.startswith(' '):
                current['legacy_dsfs'].extend(re.findall(r'/dev/rdsk/\S+', stripped))

        return disks

    def _parse_scsimgr(self, text):
        status_match = re.search(r'Generic Status:\s*(\S+)', text or '', re.IGNORECASE)
        paths_match = re.search(r'Number of Paths:\s*(\d+)', text or '', re.IGNORECASE)
        return {
            'lun_status': status_match.group(1).upper() if status_match else '',
            'path_count': self._parse_int(paths_match.group(1), 0) if paths_match else 0,
        }

    def run(self):
        expected_path_count = self.get_threshold_var('expected_path_count', default=2, value_type='int')
        required_lun_status = str(
            self.get_threshold_var('required_lun_status', default='OPTIMAL', value_type='str')
        ).strip().upper()

        rc, out, err = self._ssh(IOSCAN_COMMAND)
        if self._is_connection_error(rc, err):
            return self.fail(
                '호스트 연결 실패',
                message=(err or 'SSH 연결 확인에 실패했습니다.').strip(),
                stderr=(err or '').strip(),
            )
        if rc != 0:
            return self.fail(
                '점검 명령 실행 실패',
                message='ioscan -m dsf 명령 실행에 실패했습니다.',
                stdout=(out or '').strip(),
                stderr=(err or '').strip(),
            )

        disks = self._parse_ioscan_disks(out)
        if not disks:
            return self.fail(
                'Path 매핑 정보 없음',
                message='ioscan -m dsf 결과에서 /dev/rdisk persistent DSF를 찾지 못했습니다.',
                stdout=(out or '').strip(),
                stderr=(err or '').strip(),
            )

        disk_results = []
        failed_disks = []
        for disk in disks:
            device = disk['persistent_dsf']
            command = f'scsimgr get_info -D {device}'
            rc, scsi_out, scsi_err = self._ssh(command)

            if self._is_connection_error(rc, scsi_err):
                return self.fail(
                    '호스트 연결 실패',
                    message=(scsi_err or 'SSH 연결 확인에 실패했습니다.').strip(),
                    stderr=(scsi_err or '').strip(),
                )
            if rc != 0:
                return self.fail(
                    '점검 명령 실행 실패',
                    message=f'{command} 명령 실행에 실패했습니다.',
                    stdout=(scsi_out or '').strip(),
                    stderr=(scsi_err or '').strip(),
                )

            parsed = self._parse_scsimgr(scsi_out)
            legacy_path_count = len(disk['legacy_dsfs'])
            result = {
                'persistent_dsf': device,
                'legacy_dsfs': disk['legacy_dsfs'],
                'legacy_path_count': legacy_path_count,
                'scsimgr_path_count': parsed['path_count'],
                'lun_status': parsed['lun_status'],
            }
            disk_results.append(result)

            if (
                legacy_path_count < expected_path_count
                or parsed['path_count'] < expected_path_count
                or parsed['lun_status'] != required_lun_status
            ):
                failed_disks.append(result)

        thresholds = {
            'expected_path_count': expected_path_count,
            'required_lun_status': required_lun_status,
        }
        metrics = {
            'disk_count': len(disk_results),
            'failed_disk_count': len(failed_disks),
            'disks': disk_results,
            'failed_disks': failed_disks,
        }

        if failed_disks:
            return self.fail(
                'Path 이중화 상태 비정상',
                message=(
                    '경로 수 부족 또는 LUN 상태 비정상 디스크가 확인되었습니다: '
                    + ', '.join(
                        f"{item['persistent_dsf']}(legacy_paths={item['legacy_path_count']}, "
                        f"scsimgr_paths={item['scsimgr_path_count']}, status={item['lun_status'] or 'unknown'})"
                        for item in failed_disks
                    )
                ),
                stdout='',
            )

        return self.ok(
            metrics=metrics,
            thresholds=thresholds,
            reasons='모든 persistent DSF의 legacy path 수, scsimgr path 수, LUN 상태가 기준을 만족합니다.',
            message='ioscan/scsimgr 기준 Path 이중화 점검이 정상 수행되었습니다.',
        )


CHECK_CLASS = Check

# -*- coding: utf-8 -*-

import re
import shlex

from .common._base import BaseCheck


CONFIG = {'mode': 'ping',
 'case_name': 'hpux_network_ping_loss_check',
 'item_name': 'Ping Loss',
 'commands': ['ping 192.168.1.1 64 3'],
 'thresholds': [{'name': 'PING_LOSS_MAX_PCT', 'default': 0, 'type': 'int'},
                {'name': 'PING_LATENCY_MAX_MS', 'default': 100, 'type': 'int'},
                {'name': 'PING_TARGET', 'default': '192.168.1.1', 'type': 'str'}]}
BECOME_USER_MARKER = '__BECOME_USER__:'


class Check(BaseCheck):
    USE_HOST_CONNECTION = True
    CONNECTION_METHOD = 'ssh'
    SSH_COMMAND_TIMEOUT_SEC = 20

    def _thresholds(self):
        values = {}
        for spec in CONFIG.get('thresholds', []):
            name = spec.get('name')
            if not name:
                continue
            values[name] = self.get_threshold_var(
                name,
                default=spec.get('default'),
                value_type=spec.get('type') or 'str',
            )
        return values

    def _is_become_enabled(self):
        become_raw = self.get_application_credential_value('become', default=False)
        return str(become_raw).strip().lower() == 'true'

    def _mask_command_history(self, *secrets):
        if not self._command_history:
            return
        masked_cmd = self._command_history[-1].get('cmd', '')
        for secret in secrets:
            if secret:
                masked_cmd = masked_cmd.replace(secret, '*****')
        self._command_history[-1]['cmd'] = masked_cmd

    def _build_command(self, command):
        if not self._is_become_enabled():
            return command

        become_method = str(self.get_application_credential_value('become_method', default='su -') or 'su -').strip().lower()
        become_user = str(self.get_application_credential_value('become_user', default='root') or 'root').strip() or 'root'
        become_password = str(self.get_application_credential_value('become_password', default='') or '')
        normalized_become_method = ' '.join(become_method.split())

        if normalized_become_method not in ('su', 'su -'):
            raise ValueError(f'unsupported become_method: {become_method}')

        become_script = 'current_user=$(whoami); echo {marker}${{current_user}}; {command}'.format(
            marker=BECOME_USER_MARKER,
            command=command,
        )
        return "printf '%s\\n' {password} | su - {user} -c {command}".format(
            password=shlex.quote(become_password),
            user=shlex.quote(become_user),
            command=shlex.quote(become_script),
        )

    def _strip_become_marker(self, output):
        if not self._is_become_enabled():
            return output or '', ''

        lines = (output or '').splitlines()
        marker_line = next((line.strip() for line in lines if line.strip().startswith(BECOME_USER_MARKER)), '')
        if not marker_line:
            raise ValueError('권한 상승 후 사용자 확인 결과를 찾지 못했습니다.')

        actual_user = marker_line.split(BECOME_USER_MARKER, 1)[1].strip()
        expected_user = str(self.get_application_credential_value('become_user', default='root') or 'root').strip() or 'root'
        if actual_user != expected_user:
            raise ValueError(f'권한 상승 사용자가 기대값과 다릅니다: expected={expected_user}, actual={actual_user}')

        cleaned_lines = [line for line in lines if not line.strip().startswith(BECOME_USER_MARKER)]
        return '\n'.join(cleaned_lines).strip(), actual_user

    def _run_commands(self):
        outputs = []
        mode = CONFIG.get('mode')

        for command in CONFIG.get('commands', []):
            try:
                actual_command = self._build_command(command)
            except ValueError as exc:
                return None, self.fail('권한 상승 설정 오류', message=str(exc))

            become_password = str(self.get_application_credential_value('become_password', default='') or '')
            rc, out, err = self._ssh(actual_command)
            self._mask_command_history(become_password)

            if self._is_connection_error(rc, err):
                return None, self.fail(
                    '호스트 연결 실패',
                    message=(err or 'SSH 연결 확인에 실패했습니다.').strip(),
                    stderr=(err or '').strip(),
                )

            try:
                clean_out, actual_become_user = self._strip_become_marker(out)
            except ValueError as exc:
                return None, self.fail(
                    '권한 상승 사용자 확인 실패',
                    message=str(exc),
                    stdout=(out or '').strip(),
                    stderr=(err or '').strip(),
                )

            log_no_match = mode == 'log' and rc == 1 and not (clean_out or '').strip()
            if rc != 0 and not log_no_match:
                return None, self.fail(
                    '점검 명령 실행 실패',
                    message=f'{command} 명령 실행에 실패했습니다.',
                    stdout=(clean_out or '').strip(),
                    stderr=(err or '').strip(),
                )

            command_error = self._detect_command_error(clean_out, err)
            if command_error and not log_no_match:
                return None, self.fail(
                    '점검 명령 실행 실패',
                    message=f'{command} 명령 출력에서 실행 오류가 확인되었습니다: {command_error}',
                    stdout=(clean_out or '').strip(),
                    stderr=(err or '').strip(),
                )

            outputs.append({
                'command': command,
                'rc': rc,
                'stdout': (clean_out or '').strip(),
                'stderr': (err or '').strip(),
                'become_user': actual_become_user,
            })

        return outputs, None

    def _split_list(self, value):
        return [token.strip() for token in re.split(r'[|,\n]+', str(value or '')) if token.strip()]

    def _parse_float(self, value, default=None):
        try:
            return float(str(value).strip().rstrip('%'))
        except (TypeError, ValueError):
            return default

    def _parse_int(self, value, default=None):
        parsed = self._parse_float(value, default=None)
        if parsed is None:
            return default
        return int(parsed)

    def _combined_stdout(self, outputs):
        return '\n'.join(item.get('stdout', '') for item in outputs if item.get('stdout', '')).strip()

    def run(self):
        outputs, error = self._run_commands()
        if error:
            return error
        return self._evaluate(outputs)

    def _evaluate(self, outputs):
        thresholds = self._thresholds()
        text = outputs[0]['stdout']
        max_loss = self._parse_float(thresholds.get('PING_LOSS_MAX_PCT', 0), 0.0)
        max_latency = self._parse_float(thresholds.get('PING_LATENCY_MAX_MS', 100), 100.0)
        loss_match = re.search(r'(\d+)\s+packets\s+transmitted,\s+(\d+)\s+packets\s+received,\s+([0-9.]+)%\s+packet\s+loss', text, re.IGNORECASE)
        if not loss_match:
            return self.fail('Ping 결과 파싱 실패', message='packet loss 통계를 찾지 못했습니다.', stdout=text)
        transmitted = int(loss_match.group(1))
        received = int(loss_match.group(2))
        loss = float(loss_match.group(3))
        avg_match = re.search(r'min/avg/max\s*=\s*[0-9.]+/([0-9.]+)/[0-9.]+', text, re.IGNORECASE)
        avg_latency = float(avg_match.group(1)) if avg_match else 0.0
        if loss > max_loss or avg_latency > max_latency:
            return self.fail('Ping Loss 임계치 초과', message=f'loss={loss}%, avg_latency={avg_latency}ms가 기준을 초과했습니다.', stdout=text)
        return self.ok(metrics={'packets_transmitted': transmitted, 'packets_received': received, 'loss_percent': loss, 'avg_latency_ms': avg_latency}, thresholds={'PING_LOSS_MAX_PCT': max_loss, 'PING_LATENCY_MAX_MS': max_latency}, reasons='Ping 손실률과 지연 시간이 기준 이내입니다.', message='Ping Loss 점검이 정상 수행되었습니다.')


CHECK_CLASS = Check

# -*- coding: utf-8 -*-

import re
import shlex

from .common._base import BaseCheck


CONFIG = {'mode': 'nic_redundancy',
 'case_name': 'hpux_network_nic_redundancy_hpapa_check',
 'item_name': 'NIC 이중화 점검',
 'commands': ['netstat -in', 'lanscan -q'],
 'thresholds': [{'name': 'required_redundant_nic_count', 'default': 2, 'type': 'int'},
                {'name': 'max_interface_error_count', 'default': 0, 'type': 'int'}]}
BECOME_USER_MARKER = '__BECOME_USER__:'


class Check(BaseCheck):
    USE_HOST_CONNECTION = True
    CONNECTION_METHOD = 'ssh'

    def _thresholds(self):
        values = {}
        for spec in CONFIG.get('thresholds', []):
            name = spec.get('name')
            if not name:
                continue
            values[name] = self.get_threshold_var(
                name,
                default=spec.get('default'),
                value_type=spec.get('type') or 'str',
            )
        return values

    def _is_become_enabled(self):
        become_raw = self.get_application_credential_value('become', default=False)
        return str(become_raw).strip().lower() == 'true'

    def _mask_command_history(self, *secrets):
        if not self._command_history:
            return
        masked_cmd = self._command_history[-1].get('cmd', '')
        for secret in secrets:
            if secret:
                masked_cmd = masked_cmd.replace(secret, '*****')
        self._command_history[-1]['cmd'] = masked_cmd

    def _build_command(self, command):
        if not self._is_become_enabled():
            return command

        become_method = str(self.get_application_credential_value('become_method', default='su -') or 'su -').strip().lower()
        become_user = str(self.get_application_credential_value('become_user', default='root') or 'root').strip() or 'root'
        become_password = str(self.get_application_credential_value('become_password', default='') or '')
        normalized_become_method = ' '.join(become_method.split())

        if normalized_become_method not in ('su', 'su -'):
            raise ValueError(f'unsupported become_method: {become_method}')

        become_script = 'current_user=$(whoami); echo {marker}${{current_user}}; {command}'.format(
            marker=BECOME_USER_MARKER,
            command=command,
        )
        return "printf '%s\\n' {password} | su - {user} -c {command}".format(
            password=shlex.quote(become_password),
            user=shlex.quote(become_user),
