# -*- coding: utf-8 -*-

import re
import time

from .common._base import BaseCheck, decode_paramiko_bytes, normalize_paramiko_text


CONFIG = {'mode': 'shared_mount',
 'case_name': 'hpux_cluster_shared_volume_mount_check',
 'item_name': '공유 볼륨 상태 점검',
 'commands': ['mount'],
 'thresholds': [{'name': 'required_shared_mounts', 'default': '', 'type': 'str'},
                {'name': 'required_mount_options', 'default': 'rw', 'type': 'str'}]}
PARAMIKO_CONNECT_TIMEOUT_SEC = 10
PARAMIKO_SHELL_IDLE_SEC = 0.3
PARAMIKO_COMMAND_TIMEOUT_SEC = 30
SU_FAILURE_MESSAGES = (
    'su: sorry',
    'authentication fail',
    'login incorrect',
    'incorrect password',
    'permission denied',
)


class Check(BaseCheck):
    USE_HOST_CONNECTION = True
    CONNECTION_METHOD = 'paramiko'

    PARAMIKO_PROFILE = 'linux'
    PARAMIKO_AUTH_METHOD = 'password'
    PARAMIKO_ALLOW_AGENT = False
    PARAMIKO_LOOK_FOR_KEYS = False
    PARAMIKO_TIMEOUT_SEC = 60
    PARAMIKO_BANNER_TIMEOUT_SEC = 60
    PARAMIKO_AUTH_TIMEOUT_SEC = 60
    PARAMIKO_READ_TIMEOUT_SEC = 1.0

    def _thresholds(self):
        values = {}
        for spec in CONFIG.get('thresholds', []):
            name = spec.get('name')
            if not name:
                continue
            values[name] = self.get_threshold_var(
                name,
                default=spec.get('default'),
                value_type=spec.get('type') or 'str',
            )
        return values

    def _is_become_enabled(self):
        become_raw = self.get_application_credential_value('become', default=False)
        return str(become_raw).strip().lower() == 'true'

    def _normalize_become_method(self):
        become_method = str(self.get_application_credential_value('become_method', default='su -') or 'su -').strip().lower()
        normalized_become_method = ' '.join(become_method.split())
        if normalized_become_method not in ('su', 'su -'):
            raise ValueError(f'unsupported become_method: {become_method}')
        return normalized_become_method

    def _open_paramiko_shell(self):
        options = self._paramiko_options()
        client = None

        try:
            client = self._open_paramiko_client(options)
            channel = client.invoke_shell(term='vt100', width=160, height=48)
            channel.settimeout(0.0)
            self._read_shell_output(
                channel,
                idle_sec=PARAMIKO_SHELL_IDLE_SEC,
                timeout_sec=1.5,
            )
            return client, channel

        except Exception as exc:
            if client is not None:
                try:
                    client.close()
                except Exception:
                    pass
            raise ConnectionError(f'SSH authentication failed: {exc}') from exc

    def _read_shell_output(self, channel, idle_sec=PARAMIKO_SHELL_IDLE_SEC, timeout_sec=3.0):
        output = []
        last_data_at = time.time()
        deadline = time.time() + timeout_sec

        while time.time() < deadline:
            if channel.recv_ready():
                data = channel.recv(4096)
                if not data:
                    break
                output.append(normalize_paramiko_text(decode_paramiko_bytes(data)))
                last_data_at = time.time()
                continue
            if time.time() - last_data_at >= idle_sec:
                break
            time.sleep(0.05)

        return ''.join(output)

    def _read_until_rc_marker(self, channel, rc_marker, timeout_sec=PARAMIKO_COMMAND_TIMEOUT_SEC):
        result = self._paramiko_expect(
            channel,
            timeout_sec,
            self._resolve_paramiko_profile(self.PARAMIKO_PROFILE),
            extra_patterns=[r'(?:^|\r?\n)' + re.escape(rc_marker) + r'(?P<rc>-?\d+)\r?\n'],
            settle_timeout_sec=self.PARAMIKO_READ_TIMEOUT_SEC,
        )
        if not result.get('matched'):
            raise TimeoutError('원격 명령 실행 결과를 기다리는 중 시간이 초과되었습니다.')
        return result.get('text', '')

    def _extract_command_result(self, buffer, begin_marker, rc_marker):
        begin_pattern = re.compile(r'(?:^|\r?\n)' + re.escape(begin_marker) + r'\r?\n')
        rc_pattern = re.compile(r'(?:^|\r?\n)' + re.escape(rc_marker) + r'(?P<rc>-?\d+)\r?\n')
        begin_match = begin_pattern.search(buffer)
        if not begin_match:
            raise ValueError('명령 출력 시작 마커를 찾지 못했습니다.')
        rc_match = rc_pattern.search(buffer, begin_match.end())
        if not rc_match:
            raise ValueError('명령 종료 코드를 찾지 못했습니다.')
        output = buffer[begin_match.end():rc_match.start()]
        return int(rc_match.group('rc')), output.replace('\r', '')

    def _find_su_failure(self, text):
        lowered = (text or '').lower()
        for phrase in SU_FAILURE_MESSAGES:
            if phrase in lowered:
                return phrase
        return ''

    def _run_command_via_paramiko(self, command):
        client = None
        channel = None
        token = int(time.time() * 1000000)
        begin_marker = f'__FAP_OUTPUT_BEGIN__{token}__'
        rc_marker = f'__FAP_CMD_RC__{token}__:'
        wrapped_command = f"printf '{begin_marker}\\n'; {command}; printf '\\n{rc_marker}%s\\n' $?"

        try:
            client, channel = self._open_paramiko_shell()
            if self._is_become_enabled():
                become_user = str(self.get_application_credential_value('become_user', default='root') or 'root').strip() or 'root'
                become_password = str(self.get_application_credential_value('become_password', default='') or '')
                become_method = self._normalize_become_method()
                su_command = f"su - {become_user}" if become_method == 'su -' else f"su {become_user}"
                self._paramiko_sendline(channel, su_command)
                su_output = self._read_shell_output(channel, idle_sec=PARAMIKO_SHELL_IDLE_SEC, timeout_sec=3.0)
                self._paramiko_sendline(channel, become_password)
                auth_output = self._read_shell_output(channel, idle_sec=PARAMIKO_SHELL_IDLE_SEC, timeout_sec=5.0)
                auth_failure = self._find_su_failure('\n'.join(part for part in (su_output, auth_output) if part))
                if auth_failure:
                    combined_output = '\n'.join(part for part in (su_output, auth_output) if part).strip()
                    self._record_command(command, 1, combined_output, auth_failure)
                    return 1, combined_output, auth_failure

            self._paramiko_sendline(channel, wrapped_command)
            buffer = self._read_until_rc_marker(channel, rc_marker, timeout_sec=PARAMIKO_COMMAND_TIMEOUT_SEC)
            rc, out = self._extract_command_result(buffer, begin_marker, rc_marker)
            self._record_command(command, rc, out, '')
            return rc, out, ''
        except ConnectionError as exc:
            self._record_command(command, 255, '', str(exc))
            return 255, '', str(exc)
        except (OSError, TimeoutError, ValueError) as exc:
            self._record_command(command, 1, '', str(exc))
            return 1, '', str(exc)
        finally:
            if channel is not None:
                try:
                    channel.close()
                except Exception:
                    pass
            if client is not None:
                client.close()

    def _run_commands(self):
        outputs = []
        mode = CONFIG.get('mode')

        for command in CONFIG.get('commands', []):
            if self._is_become_enabled():
                try:
                    self._normalize_become_method()
                except ValueError as exc:
                    return None, self.fail('권한 상승 설정 오류', message=str(exc))

            rc, out, err = self._run_command_via_paramiko(command)

            if self._is_connection_error(rc, err):
                return None, self.fail(
                    '호스트 연결 실패',
                    message=(err or 'SSH 연결 확인에 실패했습니다.').strip(),
                    stderr=(err or '').strip(),
                )

            log_no_match = mode == 'log' and rc == 1 and not (out or '').strip()
            if rc != 0 and not log_no_match:
                return None, self.fail(
                    '점검 명령 실행 실패',
                    message=f'{command} 명령 실행에 실패했습니다.',
                    stdout=(out or '').strip(),
                    stderr=(err or '').strip(),
                )

            command_error = self._detect_command_error(out, err)
            if command_error and not log_no_match:
                return None, self.fail(
                    '점검 명령 실행 실패',
                    message=f'{command} 명령 출력에서 실행 오류가 확인되었습니다: {command_error}',
                    stdout=(out or '').strip(),
                    stderr=(err or '').strip(),
                )

            outputs.append({
                'command': command,
                'rc': rc,
                'stdout': (out or '').strip(),
                'stderr': (err or '').strip(),
                'become_user': str(self.get_application_credential_value('become_user', default='root') or 'root').strip() if self._is_become_enabled() else '',
            })

        return outputs, None

    def _split_list(self, value):
        return [token.strip() for token in re.split(r'[|,\n]+', str(value or '')) if token.strip()]

    def _parse_float(self, value, default=None):
        try:
            return float(str(value).strip().rstrip('%'))
        except (TypeError, ValueError):
            return default

    def _parse_int(self, value, default=None):
        parsed = self._parse_float(value, default=None)
        if parsed is None:
            return default
        return int(parsed)

    def _combined_stdout(self, outputs):
        return '\n'.join(item.get('stdout', '') for item in outputs if item.get('stdout', '')).strip()

    def _parse_mount_options(self, option_text):
        normalized = str(option_text or '').strip().strip('()')
        return [token.strip() for token in normalized.split(',') if token.strip()]

    def _is_system_mount(self, mount):
        mount_point = mount.get('mount_point', '')
        fstype = mount.get('fstype', '').lower()
        source = mount.get('source', '')
        system_fstypes = {
            'autofs',
            'bpf',
            'cgroup',
            'configfs',
            'debugfs',
            'devpts',
            'devtmpfs',
            'efivarfs',
            'fusectl',
            'hugetlbfs',
            'mqueue',
            'nsfs',
            'overlay',
            'proc',
            'pstore',
            'securityfs',
            'selinuxfs',
            'sysfs',
            'tmpfs',
            'tracefs',
        }
        system_prefixes = (
            '/dev',
            '/proc',
            '/run',
            '/sys',
            '/var/lib/docker',
        )
        if fstype in system_fstypes:
            return True
        if source in ('none', 'systemd-1'):
            return True
        return any(mount_point == prefix or mount_point.startswith(prefix + '/') for prefix in system_prefixes)

    def run(self):
        outputs, error = self._run_commands()
        if error:
            return error
        return self._evaluate(outputs)

    def _evaluate(self, outputs):
        thresholds = self._thresholds()
        text = outputs[0]['stdout']
        required_mounts = self._split_list(thresholds.get('required_shared_mounts', ''))
        required_options = self._split_list(thresholds.get('required_mount_options', 'rw'))
        mounts = []
        bad_mounts = []
        for line in text.splitlines():
            match = re.match(r'^(\S+)\s+on\s+(\S+)\s+type\s+(\S+)\s+([^\s]+)', line.strip())
            if not match:
                continue
            options = self._parse_mount_options(match.group(4))
            item = {'source': match.group(1), 'mount_point': match.group(2), 'fstype': match.group(3), 'options': options}
            mounts.append(item)

        target_mounts = [
            item for item in mounts
            if item['mount_point'] in required_mounts
        ]
        if not required_mounts:
            target_mounts = [item for item in mounts if not self._is_system_mount(item)]

        for item in target_mounts:
            if any(option not in item['options'] for option in required_options):
                bad_mounts.append(item)

        missing_mounts = [mount for mount in required_mounts if mount and not any(item['mount_point'] == mount for item in mounts)]
        if not mounts:
            return self.fail('공유 볼륨 마운트 정보 없음', message='mount 결과에서 파일시스템 마운트 정보를 찾지 못했습니다.', stdout=text)
        if missing_mounts or bad_mounts:
            return self.fail('공유 볼륨 상태 비정상', message=f'누락 마운트={missing_mounts}, 옵션 비정상={bad_mounts}', stdout=text)
        return self.ok(metrics={'mount_count': len(mounts), 'target_mount_count': len(target_mounts), 'mounts': mounts, 'target_mounts': target_mounts}, thresholds={'required_shared_mounts': '|'.join(required_mounts), 'required_mount_options': '|'.join(required_options)}, reasons='공유 볼륨이 요구 옵션으로 마운트되어 있습니다.', message='공유 볼륨 상태 점검이 정상 수행되었습니다.')


CHECK_CLASS = Check

# -*- coding: utf-8 -*-

import re
import time

from .common._base import BaseCheck, decode_paramiko_bytes, normalize_paramiko_text


CONFIG = {'mode': 'cluster_daemon',
 'case_name': 'hpux_cluster_daemon_cmviewcl_check',
 'item_name': 'Cluster 데몬 상태',
 'commands': ['cmviewcl -v'],
 'thresholds': [{'name': 'expected_cluster_status', 'default': 'up|running', 'type': 'str'},
                {'name': 'expected_package_status', 'default': 'up|running', 'type': 'str'}]}
PARAMIKO_CONNECT_TIMEOUT_SEC = 10
PARAMIKO_SHELL_IDLE_SEC = 0.3
PARAMIKO_COMMAND_TIMEOUT_SEC = 30
SU_FAILURE_MESSAGES = (
    'su: sorry',
    'authentication fail',
    'login incorrect',
    'incorrect password',
    'permission denied',
)


class Check(BaseCheck):
    USE_HOST_CONNECTION = True
    CONNECTION_METHOD = 'paramiko'

    PARAMIKO_PROFILE = 'linux'
    PARAMIKO_AUTH_METHOD = 'password'
    PARAMIKO_ALLOW_AGENT = False
    PARAMIKO_LOOK_FOR_KEYS = False
    PARAMIKO_TIMEOUT_SEC = 60
    PARAMIKO_BANNER_TIMEOUT_SEC = 60
    PARAMIKO_AUTH_TIMEOUT_SEC = 60
    PARAMIKO_READ_TIMEOUT_SEC = 1.0

    def _thresholds(self):
        values = {}
        for spec in CONFIG.get('thresholds', []):
            name = spec.get('name')
            if not name:
                continue
            values[name] = self.get_threshold_var(
                name,
                default=spec.get('default'),
                value_type=spec.get('type') or 'str',
            )
        return values

    def _is_become_enabled(self):
        become_raw = self.get_application_credential_value('become', default=False)
        return str(become_raw).strip().lower() == 'true'

    def _normalize_become_method(self):
        become_method = str(self.get_application_credential_value('become_method', default='su -') or 'su -').strip().lower()
        normalized_become_method = ' '.join(become_method.split())
        if normalized_become_method not in ('su', 'su -'):
            raise ValueError(f'unsupported become_method: {become_method}')
        return normalized_become_method

    def _open_paramiko_shell(self):
        options = self._paramiko_options()
        client = None

        try:
            client = self._open_paramiko_client(options)
            channel = client.invoke_shell(term='vt100', width=160, height=48)
            channel.settimeout(0.0)
            self._read_shell_output(
                channel,
                idle_sec=PARAMIKO_SHELL_IDLE_SEC,
                timeout_sec=1.5,
            )
            return client, channel

        except Exception as exc:
            if client is not None:
                try:
                    client.close()
                except Exception:
                    pass
            raise ConnectionError(f'SSH authentication failed: {exc}') from exc

    def _read_shell_output(self, channel, idle_sec=PARAMIKO_SHELL_IDLE_SEC, timeout_sec=3.0):
        output = []
        last_data_at = time.time()
        deadline = time.time() + timeout_sec

        while time.time() < deadline:
            if channel.recv_ready():
                data = channel.recv(4096)
                if not data:
                    break
                output.append(normalize_paramiko_text(decode_paramiko_bytes(data)))
                last_data_at = time.time()
                continue
            if time.time() - last_data_at >= idle_sec:
                break
            time.sleep(0.05)

        return ''.join(output)

    def _read_until_rc_marker(self, channel, rc_marker, timeout_sec=PARAMIKO_COMMAND_TIMEOUT_SEC):
        result = self._paramiko_expect(
            channel,
            timeout_sec,
            self._resolve_paramiko_profile(self.PARAMIKO_PROFILE),
            extra_patterns=[r'(?:^|\r?\n)' + re.escape(rc_marker) + r'(?P<rc>-?\d+)\r?\n'],
            settle_timeout_sec=self.PARAMIKO_READ_TIMEOUT_SEC,
        )
        if not result.get('matched'):
            raise TimeoutError('원격 명령 실행 결과를 기다리는 중 시간이 초과되었습니다.')
        return result.get('text', '')

    def _extract_command_result(self, buffer, begin_marker, rc_marker):
        begin_pattern = re.compile(r'(?:^|\r?\n)' + re.escape(begin_marker) + r'\r?\n')
        rc_pattern = re.compile(r'(?:^|\r?\n)' + re.escape(rc_marker) + r'(?P<rc>-?\d+)\r?\n')
        begin_match = begin_pattern.search(buffer)
        if not begin_match:
            raise ValueError('명령 출력 시작 마커를 찾지 못했습니다.')
        rc_match = rc_pattern.search(buffer, begin_match.end())
        if not rc_match:
            raise ValueError('명령 종료 코드를 찾지 못했습니다.')
        output = buffer[begin_match.end():rc_match.start()]
        return int(rc_match.group('rc')), output.replace('\r', '')

    def _find_su_failure(self, text):
        lowered = (text or '').lower()
        for phrase in SU_FAILURE_MESSAGES:
            if phrase in lowered:
                return phrase
        return ''

    def _run_command_via_paramiko(self, command):
        client = None
        channel = None
        token = int(time.time() * 1000000)
        begin_marker = f'__FAP_OUTPUT_BEGIN__{token}__'
        rc_marker = f'__FAP_CMD_RC__{token}__:'
        wrapped_command = f"printf '{begin_marker}\\n'; {command}; printf '\\n{rc_marker}%s\\n' $?"

        try:
            client, channel = self._open_paramiko_shell()
            if self._is_become_enabled():
                become_user = str(self.get_application_credential_value('become_user', default='root') or 'root').strip() or 'root'
                become_password = str(self.get_application_credential_value('become_password', default='') or '')
                become_method = self._normalize_become_method()
                su_command = f"su - {become_user}" if become_method == 'su -' else f"su {become_user}"
                self._paramiko_sendline(channel, su_command)
                su_output = self._read_shell_output(channel, idle_sec=PARAMIKO_SHELL_IDLE_SEC, timeout_sec=3.0)
                self._paramiko_sendline(channel, become_password)
                auth_output = self._read_shell_output(channel, idle_sec=PARAMIKO_SHELL_IDLE_SEC, timeout_sec=5.0)
                auth_failure = self._find_su_failure('\n'.join(part for part in (su_output, auth_output) if part))
                if auth_failure:
                    combined_output = '\n'.join(part for part in (su_output, auth_output) if part).strip()
                    self._record_command(command, 1, combined_output, auth_failure)
                    return 1, combined_output, auth_failure

            self._paramiko_sendline(channel, wrapped_command)
            buffer = self._read_until_rc_marker(channel, rc_marker, timeout_sec=PARAMIKO_COMMAND_TIMEOUT_SEC)
            rc, out = self._extract_command_result(buffer, begin_marker, rc_marker)
            self._record_command(command, rc, out, '')
            return rc, out, ''
        except ConnectionError as exc:
            self._record_command(command, 255, '', str(exc))
            return 255, '', str(exc)
        except (OSError, TimeoutError, ValueError) as exc:
            self._record_command(command, 1, '', str(exc))
            return 1, '', str(exc)
        finally:
            if channel is not None:
                try:
                    channel.close()
                except Exception:
                    pass
            if client is not None:
                client.close()

    def _run_commands(self):
        outputs = []
        mode = CONFIG.get('mode')

        for command in CONFIG.get('commands', []):
            if self._is_become_enabled():
                try:
                    self._normalize_become_method()
                except ValueError as exc:
                    return None, self.fail('권한 상승 설정 오류', message=str(exc))

            rc, out, err = self._run_command_via_paramiko(command)

            if self._is_connection_error(rc, err):
                return None, self.fail(
                    '호스트 연결 실패',
                    message=(err or 'SSH 연결 확인에 실패했습니다.').strip(),
                    stderr=(err or '').strip(),
                )

            log_no_match = mode == 'log' and rc == 1 and not (out or '').strip()
            if rc != 0 and not log_no_match:
                return None, self.fail(
                    '점검 명령 실행 실패',
                    message=f'{command} 명령 실행에 실패했습니다.',
                    stdout=(out or '').strip(),
                    stderr=(err or '').strip(),
                )

            command_error = self._detect_command_error(out, err)
            if command_error and not log_no_match:
                return None, self.fail(
                    '점검 명령 실행 실패',
                    message=f'{command} 명령 출력에서 실행 오류가 확인되었습니다: {command_error}',
                    stdout=(out or '').strip(),
                    stderr=(err or '').strip(),
                )

            outputs.append({
                'command': command,
                'rc': rc,
                'stdout': (out or '').strip(),
                'stderr': (err or '').strip(),
                'become_user': str(self.get_application_credential_value('become_user', default='root') or 'root').strip() if self._is_become_enabled() else '',
            })

        return outputs, None

    def _split_list(self, value):
        return [token.strip() for token in re.split(r'[|,\n]+', str(value or '')) if token.strip()]

    def _parse_float(self, value, default=None):
        try:
            return float(str(value).strip().rstrip('%'))
        except (TypeError, ValueError):
            return default

    def _parse_int(self, value, default=None):
        parsed = self._parse_float(value, default=None)
        if parsed is None:
            return default
        return int(parsed)

    def _combined_stdout(self, outputs):
        return '\n'.join(item.get('stdout', '') for item in outputs if item.get('stdout', '')).strip()

    def run(self):
        outputs, error = self._run_commands()
        if error:
            return error
        return self._evaluate(outputs)

    def _evaluate(self, outputs):
        thresholds = self._thresholds()
        text = outputs[0]['stdout']
        cluster_expected = {token.lower() for token in self._split_list(thresholds.get('expected_cluster_status', 'up|running'))}
        package_expected = {token.lower() for token in self._split_list(thresholds.get('expected_package_status', 'up|running'))}
        bad_pattern = r'\b(down|halted|unknown|failed|error|offline|maintenance)\b'
        lines = [line.strip() for line in text.splitlines() if line.strip()]
        cluster_rows = []
        node_rows = []
        package_rows = []
        bad_lines = []
        section = ''

        for line in lines:
            lower = line.lower()
            if lower.startswith('node') and 'status' in lower:
                section = 'node'
                continue
            if lower.startswith('package') and 'status' in lower:
                section = 'package'
                continue
            if lower.startswith('cluster') and 'status' in lower:
                section = 'cluster'
                continue
            if re.search(bad_pattern, line, re.IGNORECASE):
                bad_lines.append(line)

            parts = line.split()
            if len(parts) < 2:
                continue
            if section == 'node':
                status = parts[1].lower()
                state = parts[2].lower() if len(parts) > 2 else ''
                node_rows.append({'name': parts[0], 'status': status, 'state': state})
                if status not in cluster_expected or (state and state not in cluster_expected):
                    bad_lines.append(line)
            elif section == 'package':
                status = parts[1].lower()
                state = parts[2].lower() if len(parts) > 2 else ''
                package_rows.append({'name': parts[0], 'status': status, 'state': state})
                if status not in package_expected or (state and state not in package_expected):
                    bad_lines.append(line)
            elif section == 'cluster':
                status = parts[1].lower()
                cluster_rows.append({'name': parts[0], 'status': status})
                if status not in cluster_expected:
                    bad_lines.append(line)

        bad_lines = list(dict.fromkeys(bad_lines))
        metrics = {
            'cluster_count': len(cluster_rows),
            'node_count': len(node_rows),
            'package_count': len(package_rows),
            'clusters': cluster_rows,
            'nodes': node_rows,
            'packages': package_rows,
            'bad_lines': bad_lines,
        }
        threshold_data = {
            'expected_cluster_status': '|'.join(sorted(cluster_expected)),
            'expected_package_status': '|'.join(sorted(package_expected)),
        }

        if not cluster_rows or not node_rows:
            return self.fail('클러스터 상태 정보 없음', message='cmviewcl 결과에서 클러스터 또는 노드 상태 정보를 찾지 못했습니다.', stdout=text)
        if bad_lines:
            return self.fail('클러스터 상태 비정상', message='비정상 클러스터 상태가 확인되었습니다: ' + ', '.join(bad_lines), stdout=text)

        return self.ok(metrics=metrics, thresholds=threshold_data, reasons='클러스터와 노드/패키지 상태가 정상입니다.', message='Serviceguard 클러스터 상태 점검이 정상 수행되었습니다.')


CHECK_CLASS = Check

# -*- coding: utf-8 -*-

import re
import shlex

from .common._base import BaseCheck


BASE_COMMAND = 'dmesg'
BAD_KEY = 'io_bad_log_keywords'
IGNORE_KEY = 'io_ignore_log_keywords'
FAIL_ERROR = 'I/O 장애 로그 감지'
LOG_LABEL = 'I/O 장애 로그'
ITEM_LABEL = 'I/O 에러로그'


class Check(BaseCheck):
    USE_HOST_CONNECTION = True
    CONNECTION_METHOD = 'ssh'

    def _split_patterns(self, value):
        return [
            token.strip()
            for token in re.split(r'[|,\n]+', str(value or ''))
            if token.strip()
        ]

    def _matches_any(self, line, patterns):
        matched = []
        for pattern in patterns:
            try:
                if re.search(pattern, line, re.IGNORECASE):
                    matched.append(pattern)
            except re.error:
                if pattern.lower() in line.lower():
                    matched.append(pattern)
        return matched

    def run(self):
        bad_raw = self.get_threshold_var(BAD_KEY, default='', value_type='str')
        ignore_raw = self.get_threshold_var(IGNORE_KEY, default='', value_type='str')
        bad_patterns = self._split_patterns(bad_raw)
        ignore_patterns = self._split_patterns(ignore_raw)

        if not bad_patterns:
            return self.fail(
                '임계치 미정의',
                message=f'{BAD_KEY} 값이 비어 있어 egrep 패턴을 만들 수 없습니다.',
            )

        command = f'{BASE_COMMAND} | egrep -i {shlex.quote("|".join(bad_patterns))}'
        rc, out, err = self._ssh(command)

        if self._is_connection_error(rc, err):
            return self.fail(
                '호스트 연결 실패',
                message=(err or 'SSH 연결 확인에 실패했습니다.').strip(),
                stderr=(err or '').strip(),
            )

        if rc not in (0, 1):
            return self.fail(
                '점검 명령 실행 실패',
                message=f'{command} 명령 실행에 실패했습니다.',
                stdout=(out or '').strip(),
                stderr=(err or '').strip(),
            )

        if 'REPLAY_MISS:' in (err or ''):
            return self.fail(
                'replay 명령 불일치',
                message=(err or '').strip(),
                stdout=(out or '').strip(),
                stderr=(err or '').strip(),
            )

        command_error = self._detect_command_error(out, err)
        if command_error:
            return self.fail(
                '점검 명령 실행 실패',
                message=f'{command} 명령 출력에서 실행 오류가 확인되었습니다: {command_error}',
                stdout=(out or '').strip(),
                stderr=(err or '').strip(),
            )

        ignored_lines = []
        bad_matches = []
        for line in [line.strip() for line in (out or '').splitlines() if line.strip()]:
            ignore_matches = self._matches_any(line, ignore_patterns)
            if ignore_matches:
                ignored_lines.append({
                    'line': line,
                    'matched_patterns': ignore_matches,
                })
                continue

            matched = self._matches_any(line, bad_patterns)
            if matched:
                bad_matches.append({
                    'line': line,
                    'matched_patterns': matched,
                })

        metrics = {
            'command': command,
            'command_rc': rc,
            'log_line_count': len(ignored_lines) + len(bad_matches),
            'ignored_line_count': len(ignored_lines),
            'bad_match_count': len(bad_matches),
            'ignored_lines': ignored_lines,
            'bad_matches': bad_matches,
        }
        thresholds = {
            BAD_KEY: '|'.join(bad_patterns),
            IGNORE_KEY: '|'.join(ignore_patterns),
        }

        if bad_matches:
            return self.fail(
                FAIL_ERROR,
                message=(
                    f'{LOG_LABEL} {len(bad_matches)}건이 확인되었습니다. '
                    f'ignore 제외={len(ignored_lines)}건, 기준={thresholds[BAD_KEY]}.'
                ),
                stdout=(out or '').strip(),
            )

        return self.ok(
            metrics=metrics,
            thresholds=thresholds,
            reasons=f'{LOG_LABEL}가 확인되지 않았습니다.',
            message=f'{ITEM_LABEL} 점검이 정상 수행되었습니다.',
        )


CHECK_CLASS = Check

