        try:
            return float(str(value).strip().rstrip('%'))
        except (TypeError, ValueError):
            return default

    def _parse_int(self, value, default=None):
        parsed = self._parse_float(value, default=None)
        if parsed is None:
            return default
        return int(parsed)

    def _combined_stdout(self, outputs):
        return '\n'.join(item.get('stdout', '') for item in outputs if item.get('stdout', '')).strip()

    def run(self):
        outputs, error = self._run_commands()
        if error:
            return error
        return self._evaluate(outputs)

    def _evaluate(self, outputs):
        thresholds = self._thresholds()
        text = outputs[0]['stdout']
        required = self._split_list(thresholds.get('required_kernel_parameters', ''))
        tunables = {}
        for line in text.splitlines():
            parts = line.split()
            if len(parts) >= 2 and parts[0] != 'Tunable':
                tunables[parts[0]] = parts[1]
        missing = [name for name in required if name and name not in tunables]
        if missing:
            return self.fail('커널 파라미터 누락', message='필수 커널 파라미터가 확인되지 않습니다: ' + ', '.join(missing), stdout=text)
