            return self.fail('커널 파라미터 정보 없음', message='kctune 결과에서 튜너블 값을 찾지 못했습니다.', stdout=text)
        return self.ok(metrics={'tunable_count': len(tunables), 'tunables': tunables}, thresholds={'required_kernel_parameters': '|'.join(required)}, reasons='커널 파라미터 조회가 정상 수행되었습니다.', message='kctune 기준 Kernel Parameter 점검이 정상 수행되었습니다.')


