            rows.append({'type': parts[0], 'avail_mb': self._parse_float(parts[1], 0.0), 'used_mb': self._parse_float(parts[2], 0.0), 'free_mb': self._parse_float(parts[3], 0.0), 'used_percent': self._parse_float(parts[4], 0.0), 'raw_line': line})
